"use client";

import Link from 'next/link';
import { useEffect, useState } from 'react';
import {
  ArrowLeftRight,
  ArrowRight,
  Handshake,
  Loader2,
  Shield,
  TrendingUp,
  User,
} from 'lucide-react';

import GameLayout from '@/components/GameLayout';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Slider } from '@/components/ui/slider';
import { useToast } from '@/hooks/use-toast';
import { RTGPostBlockResponse, RTGSubmitTrialResponse, SessionState, rtgAPI } from '@/lib/api';

type PartnerClassification = 'high_return' | 'low_return' | 'unpredictable';

function MainCharacter({
  name,
  badge,
  isPlayer = false,
}: {
  name: string;
  badge: string;
  isPlayer?: boolean;
}) {
  return (
    <div className="flex min-w-[120px] flex-col items-center rounded-2xl border border-slate-200/80 bg-white/85 px-4 py-4 shadow-sm">
      <div
        className={`mb-2 flex h-12 w-12 items-center justify-center rounded-full border-4 ${
          isPlayer
            ? 'border-blue-300 bg-blue-100 text-blue-700'
            : 'border-purple-300 bg-purple-100 text-purple-700'
        }`}
      >
        {isPlayer ? <User className="h-6 w-6" /> : <Shield className="h-6 w-6" />}
      </div>
      <div className="text-sm font-medium text-slate-700">{name}</div>
      <div className="mt-3 rounded-full bg-slate-900 px-3 py-1 text-sm font-semibold text-white">
        {badge}
      </div>
    </div>
  );
}

function PayoffBarChart({
  cumulativePayoff,
  amountSent,
  amountReturned,
}: {
  cumulativePayoff: number;
  amountSent: number;
  amountReturned: number;
}) {
  const values = [
    { label: 'Cumulative', value: cumulativePayoff, color: 'bg-blue-500' },
    { label: 'Sent', value: amountSent, color: 'bg-rose-500' },
    { label: 'Returned', value: amountReturned, color: 'bg-emerald-500' },
  ];
  const maxValue = Math.max(...values.map((item) => item.value), 1);

  return (
    <div className="rounded-2xl border border-blue-200 bg-gradient-to-r from-blue-50 to-indigo-50 p-4">
      <div className="mb-4 flex items-center gap-2 text-sm font-semibold text-slate-700">
        <TrendingUp className="h-4 w-4" />
        Payoff Snapshot
      </div>
      <div className="flex h-40 items-end justify-center gap-5">
        {values.map((item) => (
          <div key={item.label} className="flex flex-col items-center">
            <div className="mb-2 text-xs font-medium text-slate-600">{item.label}</div>
            <div className="relative h-24 w-14 overflow-hidden rounded-xl border border-slate-200 bg-white">
              <div
                className={`absolute bottom-0 w-full rounded-b-xl ${item.color} transition-all duration-500 ease-out`}
                style={{ height: `${Math.max((item.value / maxValue) * 100, item.value > 0 ? 10 : 0)}%` }}
              />
              <div className="absolute inset-x-0 top-2 text-center text-xs font-bold text-slate-700">
                {item.value.toFixed(1)}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default function RTGMainPage() {
  const [session, setSession] = useState<SessionState | null>(null);
  const [amountSent, setAmountSent] = useState<number[]>([0]);
  const [classification, setClassification] = useState<PartnerClassification>('high_return');
  const [confidence, setConfidence] = useState<number[]>([4]);
  const [willingness, setWillingness] = useState<number[]>([4]);
  const [lastTrial, setLastTrial] = useState<RTGSubmitTrialResponse | null>(null);
  const [lastPostBlock, setLastPostBlock] = useState<RTGPostBlockResponse | null>(null);
  const [promptStartedAt, setPromptStartedAt] = useState<number>(Date.now());
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();

  const rules = [
    '참가자는 항상 trustor 역할입니다.',
    '세 명의 partner와 각각 15번씩 상호작용합니다.',
    '각 trial의 endowment는 10포인트이며 보낸 금액은 3배가 되어 partner에게 전달됩니다.',
    '각 block이 끝나면 partner 분류, 확신도, 재참여 의향을 기록합니다.',
  ];

  useEffect(() => {
    if (session?.phase === 'trial') {
      setAmountSent([0]);
      setPromptStartedAt(Date.now());
    }
  }, [session?.phase, session?.overall_trial_index, session?.current_block_index]);

  const handleStart = async () => {
    setIsLoading(true);
    try {
      const response = await rtgAPI.startSession();
      setSession(response.session);
      setLastTrial(null);
      setLastPostBlock(null);
    } catch (error) {
      toast({
        title: '본실험 시작 실패',
        description:
          error instanceof Error
            ? error.message
            : 'RTG 본실험을 시작하지 못했습니다.',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmitTrial = async () => {
    if (!session) return;

    setIsLoading(true);
    try {
      const response = await rtgAPI.submitTrial({
        session_id: session.session_id,
        amount_sent: amountSent[0],
        response_time_ms: Date.now() - promptStartedAt,
      });
      setSession(response.session);
      setLastTrial(response);
      setLastPostBlock(null);
      toast({
        title: `Trial ${response.trial.rtg_trial_index} 완료`,
        description: `${response.trial.partner_return_amount.toFixed(2)} points를 돌려받았습니다.`,
      });
    } catch (error) {
      toast({
        title: '제출 실패',
        description: error instanceof Error ? error.message : 'RTG trial 제출에 실패했습니다.',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmitPostBlock = async () => {
    if (!session) return;

    setIsLoading(true);
    try {
      const response = await rtgAPI.submitPostBlock({
        session_id: session.session_id,
        partner_classification_response: classification,
        classification_confidence: confidence[0],
        willingness_to_play_again: willingness[0],
      });
      setSession(response.session);
      setLastPostBlock(response);
      setLastTrial(null);
      setClassification('high_return');
      setConfidence([4]);
      setWillingness([4]);
      toast({
        title: `Block ${response.post_block.rtg_block_index} 저장 완료`,
        description: response.completed
          ? 'RTG 본실험이 완료되었습니다.'
          : '다음 partner block으로 이동합니다.',
      });
    } catch (error) {
      toast({
        title: 'Post-block 저장 실패',
        description: error instanceof Error ? error.message : 'Post-block 응답 저장에 실패했습니다.',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleNextTrial = () => {
    setLastTrial(null);
    setAmountSent([0]);
    setPromptStartedAt(Date.now());
  };

  const currentRound =
    session?.overall_trial_index ??
    session?.completed_trials_count ??
    1;
  const totalRounds =
    (session?.total_blocks ?? 3) * (session?.trials_per_block ?? 15);

  return (
    <GameLayout
      title="Repeated Trust Game"
      rules={rules}
      currentRound={Math.min(currentRound, totalRounds)}
      totalRounds={totalRounds}
      playerBalance={session?.cumulative_payoff ?? 0}
      balanceLabel="Cumulative Payoff"
      showSidebar={!session}
    >
      {!session && (
        <Card className="mx-auto w-full max-w-2xl border-none bg-transparent shadow-none">
          <CardHeader>
            <CardTitle className="text-center text-3xl text-primary">Repeated Trust Game</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4 text-center text-foreground/80">
            <p>
              본실험에서는 trustor로서 세 명의 partner와 반복 상호작용합니다. 먼저 tutorial과
              이해도 점검을 끝냈는지 확인한 뒤 시작하세요.
            </p>
            <div className="rounded-2xl border border-primary/20 bg-primary/5 px-5 py-4">
              <div className="text-sm text-primary/70">Main Task Structure</div>
              <div className="mt-1 text-2xl font-bold text-primary">3 Partners x 15 Trials</div>
            </div>
          </CardContent>
          <CardFooter className="flex justify-between">
            <Button asChild variant="outline">
              <Link href="/trust-game/tutorial">Tutorial First</Link>
            </Button>
            <Button onClick={handleStart} disabled={isLoading}>
              {isLoading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Handshake className="mr-2 h-4 w-4" />}
              Start Main Task
            </Button>
          </CardFooter>
        </Card>
      )}

      {session?.phase === 'trial' && (
        <Card className="border-primary/10 shadow-lg">
          <CardHeader>
            <CardTitle className="text-primary">
              {session.current_partner_label} · Block {session.current_block_index}/{session.total_blocks} · Trial{' '}
              {session.current_trial_within_block}/{session.trials_per_block}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="rounded-3xl border border-slate-100 bg-slate-50/70 p-5">
              <div className="flex flex-wrap items-center justify-center gap-5">
                <MainCharacter
                  name="You"
                  badge={`${amountSent[0]} sent`}
                  isPlayer
                />
                <div className="flex min-w-[150px] flex-col items-center text-center text-slate-600">
                  <ArrowLeftRight className="mb-2 h-8 w-8 text-blue-500" />
                  <div className="text-sm">Partner receives</div>
                  <div className="text-3xl font-bold text-blue-600">
                    {(amountSent[0] * (session.multiplier ?? 3)).toFixed(1)}
                  </div>
                  <div className="text-xs">after multiplier</div>
                </div>
                <MainCharacter
                  name={session.current_partner_label ?? 'Partner'}
                  badge={
                    lastTrial
                      ? `${lastTrial.trial.partner_return_amount.toFixed(1)} back`
                      : 'awaiting'
                  }
                />
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between text-sm text-slate-600">
                <span>Amount Sent</span>
                <span className="text-lg font-semibold text-primary">{amountSent[0]} points</span>
              </div>
              <Slider
                min={0}
                max={session.endowment ?? 10}
                step={1}
                value={amountSent}
                onValueChange={setAmountSent}
              />
              <div className="flex justify-between text-xs text-slate-500">
                <span>Keep all</span>
                <span>Send all</span>
              </div>
            </div>

            <PayoffBarChart
              cumulativePayoff={session.cumulative_payoff ?? 0}
              amountSent={amountSent[0]}
              amountReturned={lastTrial?.trial.partner_return_amount ?? 0}
            />
          </CardContent>
          <CardFooter className="justify-end">
            <Button onClick={handleSubmitTrial} disabled={isLoading}>
              {isLoading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
              Submit Trial
            </Button>
          </CardFooter>
        </Card>
      )}

      {lastTrial && (
        <Card className="mt-4 border-emerald-200 bg-emerald-50 shadow-lg">
          <CardHeader>
            <CardTitle className="text-emerald-900">Latest RTG Result</CardTitle>
          </CardHeader>
          <CardContent className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <div className="rounded-xl bg-white p-4">
              <div className="text-sm text-slate-500">Amount Sent</div>
              <div className="mt-1 text-2xl font-bold">{lastTrial.trial.amount_sent}</div>
            </div>
            <div className="rounded-xl bg-white p-4">
              <div className="text-sm text-slate-500">Partner Received</div>
              <div className="mt-1 text-2xl font-bold">{lastTrial.trial.amount_received_by_partner}</div>
            </div>
            <div className="rounded-xl bg-white p-4">
              <div className="text-sm text-slate-500">Partner Returned</div>
              <div className="mt-1 text-2xl font-bold">{lastTrial.trial.partner_return_amount}</div>
            </div>
            <div className="rounded-xl bg-white p-4">
              <div className="text-sm text-slate-500">Trial Payoff</div>
              <div className="mt-1 text-2xl font-bold">{lastTrial.trial.participant_total_payoff_this_trial}</div>
            </div>
          </CardContent>
          {session?.phase === 'trial' && (
            <CardFooter className="justify-end">
              <Button variant="outline" onClick={handleNextTrial}>
                Next Trial
              </Button>
            </CardFooter>
          )}
        </Card>
      )}

      {session?.phase === 'awaiting_post_block' && (
        <Card className="mt-4 shadow-lg">
          <CardHeader>
            <CardTitle className="text-primary">
              Post-block Perception · {session.current_partner_label}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="space-y-2">
              <div className="font-medium">이 상대는 전반적으로 어떤 유형이었던 것 같나요?</div>
              <RadioGroup value={classification} onValueChange={(value) => setClassification(value as PartnerClassification)}>
                <div className="flex items-center gap-3 rounded-xl border px-4 py-3">
                  <RadioGroupItem value="high_return" id="class-high" />
                  <Label htmlFor="class-high">대체로 많이 돌려주는 편</Label>
                </div>
                <div className="flex items-center gap-3 rounded-xl border px-4 py-3">
                  <RadioGroupItem value="low_return" id="class-low" />
                  <Label htmlFor="class-low">대체로 적게 돌려주는 편</Label>
                </div>
                <div className="flex items-center gap-3 rounded-xl border px-4 py-3">
                  <RadioGroupItem value="unpredictable" id="class-unpredictable" />
                  <Label htmlFor="class-unpredictable">들쭉날쭉하고 예측하기 어려운 편</Label>
                </div>
              </RadioGroup>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between text-sm text-slate-600">
                <span>분류 확신도</span>
                <span className="font-semibold text-primary">{confidence[0]} / 7</span>
              </div>
              <Slider min={1} max={7} step={1} value={confidence} onValueChange={setConfidence} />
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between text-sm text-slate-600">
                <span>다시 게임하고 싶은 정도</span>
                <span className="font-semibold text-primary">{willingness[0]} / 7</span>
              </div>
              <Slider min={1} max={7} step={1} value={willingness} onValueChange={setWillingness} />
            </div>
          </CardContent>
          <CardFooter className="justify-end">
            <Button onClick={handleSubmitPostBlock} disabled={isLoading}>
              {isLoading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
              Save Post-block Response
            </Button>
          </CardFooter>
        </Card>
      )}

      {lastPostBlock && session?.phase !== 'completed' && (
        <Card className="mt-4 border-blue-200 bg-blue-50 shadow-lg">
          <CardHeader>
            <CardTitle className="text-blue-900">Block Saved</CardTitle>
          </CardHeader>
          <CardContent className="text-foreground/80">
            {lastPostBlock.post_block.partner_public_label}에 대한 평가가 저장되었습니다. 다음 block으로 이동합니다.
          </CardContent>
        </Card>
      )}

      {session?.phase === 'completed' && (
        <Card className="mx-auto mt-4 w-full max-w-2xl shadow-xl">
          <CardHeader>
            <CardTitle className="text-3xl text-primary">RTG Completed</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3 text-foreground/80">
            <p>3개 partner와의 45개 trial을 모두 완료했습니다.</p>
            <p>
              누적 payoff는 <strong className="text-primary">{session.cumulative_payoff?.toFixed(2)} points</strong>입니다.
            </p>
            <p>이제 결과 리포트를 확인하거나 설문 단계로 넘어갈 수 있습니다.</p>
          </CardContent>
          <CardFooter className="flex justify-between">
            <Button asChild variant="outline">
              <Link href="/report">Open Report</Link>
            </Button>
            <Button asChild>
              <Link href="/questionnaire">
                Continue to Questionnaire
                <ArrowRight className="ml-2 h-4 w-4" />
              </Link>
            </Button>
          </CardFooter>
        </Card>
      )}
    </GameLayout>
  );
}
